"""Deterministic datasets generated by the reference PDE solvers."""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

from .burgers import integrate_burgers


@dataclass(frozen=True)
class BurgersDataset:
    """A traceable initial-condition to solution-operator dataset."""

    inputs: np.ndarray
    targets: np.ndarray
    length: float
    dt: float
    steps: int
    viscosity: float
    seed: int
    modes: int = 4
    amplitude: float = 0.5
    forcing_amplitude: float = 0.0
    forcing_mode: int = 1
    forcing: np.ndarray | None = None

    @property
    def resolution(self) -> int:
        return int(self.inputs.shape[1])

    @property
    def samples(self) -> int:
        return int(self.inputs.shape[0])

    @property
    def horizon(self) -> float:
        """Return the physical duration represented by each input/target pair."""

        return float(self.dt * self.steps)


def random_periodic_fields(
    samples: int,
    points: int,
    modes: int = 4,
    seed: int = 0,
    length: float = 2.0 * np.pi,
    amplitude: float = 0.5,
) -> np.ndarray:
    """Generate smooth, band-limited periodic initial conditions."""

    if not isinstance(samples, (int, np.integer)) or samples <= 0:
        raise ValueError("samples must be a positive integer")
    if not isinstance(points, (int, np.integer)) or points < 4:
        raise ValueError("points must be an integer greater than or equal to 4")
    if not isinstance(modes, (int, np.integer)) or modes <= 0 or modes >= points // 2:
        raise ValueError("modes must be positive and below the Nyquist limit")
    if not np.isfinite(length) or length <= 0.0:
        raise ValueError("length must be finite and strictly positive")
    if not np.isfinite(amplitude) or amplitude < 0.0:
        raise ValueError("amplitude must be finite and non-negative")

    rng = np.random.default_rng(seed)
    x = np.arange(int(points)) * float(length) / int(points)
    fields = np.zeros((int(samples), int(points)), dtype=float)
    for mode in range(1, int(modes) + 1):
        scale = float(amplitude) / np.sqrt(float(mode))
        fields += scale * rng.normal(size=(int(samples), 1)) * np.sin(mode * x)
        fields += scale * rng.normal(size=(int(samples), 1)) * np.cos(mode * x)
    fields += 0.1 * rng.normal(size=(int(samples), 1))
    return fields


def periodic_forcing_field(
    points: int,
    length: float = 2.0 * np.pi,
    amplitude: float = 0.0,
    mode: int = 1,
) -> np.ndarray:
    """Create a static sinusoidal forcing field on the periodic grid."""

    if not isinstance(points, (int, np.integer)) or points < 4:
        raise ValueError("points must be an integer greater than or equal to 4")
    if not np.isfinite(length) or length <= 0.0:
        raise ValueError("length must be finite and strictly positive")
    if not np.isfinite(amplitude) or amplitude < 0.0:
        raise ValueError("amplitude must be finite and non-negative")
    if not isinstance(mode, (int, np.integer)) or mode <= 0 or mode >= points // 2:
        raise ValueError("mode must be positive and below the Nyquist limit")

    x = np.arange(int(points), dtype=float) * float(length) / int(points)
    return float(amplitude) * np.sin(2.0 * np.pi * int(mode) * x / float(length))


def generate_burgers_dataset(
    samples: int,
    points: int,
    dt: float,
    steps: int,
    viscosity: float,
    seed: int = 0,
    length: float = 2.0 * np.pi,
    modes: int = 4,
    amplitude: float = 0.5,
    forcing_amplitude: float = 0.0,
    forcing_mode: int = 1,
) -> BurgersDataset:
    """Generate u(0) -> u(steps*dt) pairs with full provenance."""

    initial_fields = random_periodic_fields(
        samples=samples,
        points=points,
        modes=modes,
        seed=seed,
        length=length,
        amplitude=amplitude,
    )
    forcing = periodic_forcing_field(
        points=points,
        length=length,
        amplitude=forcing_amplitude,
        mode=forcing_mode,
    )
    trajectory = integrate_burgers(
        initial_fields,
        dt=dt,
        steps=steps,
        viscosity=viscosity,
        length=length,
        forcing=forcing,
    )
    return BurgersDataset(
        inputs=initial_fields[..., None],
        targets=trajectory[-1][..., None],
        length=float(length),
        dt=float(dt),
        steps=int(steps),
        viscosity=float(viscosity),
        seed=int(seed),
        modes=int(modes),
        amplitude=float(amplitude),
        forcing_amplitude=float(forcing_amplitude),
        forcing_mode=int(forcing_mode),
        forcing=forcing,
    )
